        private static GameDefineEntry Integer(
            string id, string name, string description, GameDefineCategory category,
            string unit, int value, int minimum, int maximum)
        {
            return new GameDefineEntry
            {
                Id = id, DisplayName = name, Description = description, Category = category,
                Unit = unit, ValueType = GameDefineValueType.Integer,
                DefaultIntegerValue = value, CurrentIntegerValue = value,
                MinimumIntegerValue = minimum, MaximumIntegerValue = maximum
            };
        }

        private static GameDefineEntry Float(
            string id, string name, string description, GameDefineCategory category,
            string unit, float value, float minimum, float maximum)
        {
            return new GameDefineEntry
            {
                Id = id, DisplayName = name, Description = description, Category = category,
                Unit = unit, ValueType = GameDefineValueType.Float,
                DefaultFloatValue = value, CurrentFloatValue = value,
                MinimumFloatValue = minimum, MaximumFloatValue = maximum
            };
        }
    }
